    "text": "そうですか。じゃあ、まずは新しい指導形式を導入するほう。具体的な価格や時間数のシミュレーションをしてみてください。幼児を対象にしたクラスのほうは内容を詰めるのに時間がかかるだろうから、おいおい考えていきましょう。",
